import{_ as t,o,c as a,a2 as r}from"./chunks/framework.BN3Eol-0.js";const m=JSON.parse('{"title":"UXD-044 — Moon traverses take the Mars line style: the ramp by distance, casing, kilometre milestones, landing ring and a km hover card; the two 9-point routes are labelled \\"Approximate route\\"","description":"","frontmatter":{},"headers":[],"relativePath":"uxs/decisions/UXD-044-moon-traverses-take-the-mars-line-style.md","filePath":"uxs/decisions/UXD-044-moon-traverses-take-the-mars-line-style.md"}'),s={name:"uxs/decisions/UXD-044-moon-traverses-take-the-mars-line-style.md"};function n(i,e,d,l,c,h){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="uxd-044-—-moon-traverses-take-the-mars-line-style-the-ramp-by-distance-casing-kilometre-milestones-landing-ring-and-a-km-hover-card-the-two-9-point-routes-are-labelled-approximate-route" tabindex="-1">UXD-044 — Moon traverses take the Mars line style: the ramp by distance, casing, kilometre milestones, landing ring and a km hover card; the two 9-point routes are labelled &quot;Approximate route&quot; <a class="header-anchor" href="#uxd-044-—-moon-traverses-take-the-mars-line-style-the-ramp-by-distance-casing-kilometre-milestones-landing-ring-and-a-km-hover-card-the-two-9-point-routes-are-labelled-approximate-route" aria-label="Permalink to &quot;UXD-044 — Moon traverses take the Mars line style: the ramp by distance, casing, kilometre milestones, landing ring and a km hover card; the two 9-point routes are labelled &quot;Approximate route&quot;&quot;">​</a></h1><ul><li><strong>Status</strong>: accepted (built; unit tests green, browser checks listed under Verification)</li><li><strong>Date</strong>: 2026-11-15</li><li><strong>Decider</strong>: the operator, 2026-11-13 — &quot;Ok with all 12&quot; (decisions 10a, 11a, 12a of <code>docs/wip/2026-11-13-slice-D4-brief.md</code> §12; Q8 answered: line style only)</li><li><strong>Answers</strong>: WM2, L49 of the UX feedback plan; Q8; slice D4</li><li><strong>Builds on</strong>: <a href="./UXD-001-ui-accent-blue-replaces-teal">UXD-001</a> (the ramp is a data colour, <code>a3-keep</code>), ADR-072 (surface routes share one scene), #641 (the Mars sol ramp, ticks, milestones)</li><li><strong>Changes</strong>: <code>src/lib/surface-scene/surface-traverses.ts</code> (<code>TRAVERSE_STYLE</code>, <code>cumulativeKm</code>, <code>traverseRampParams</code>; ramp, milestones, landing ring and hover for every route), <code>surface-picking.ts</code> (hover without sols), <code>SurfaceScene.svelte</code> (the &quot;Approximate route&quot; line), <code>src/types/surface-site.ts</code> and <code>static/data/schemas/traverse.schema.json</code> (<code>approximate</code>), <code>static/data/moon-traverses/change3.json</code>, <code>chandrayaan3.json</code>, <code>scripts/hotspots/build-moon-traverses.mjs</code>, <code>messages/*.json</code> (<code>traverse_hover_km</code>, <code>traverse_approximate_route</code>), tests (<code>surface-traverses.test.ts</code>, <code>.build.test.ts</code>, <code>moon-traverses.data.test.ts</code>, <code>src/routes/library/source-ids.test.ts</code>). No image, no dependency changed.</li></ul><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>The Mars routes read sol, length, landing sol, elevation and photo fields the Moon files do not have, so the Moon routes were drawn in the nation colour with none of the Mars furniture. Six of the eight Moon routes are real mapped tracks (LROC NAC or USGS); Chang&#39;e 3 (Yutu) and Chandrayaan-3 (Pragyan) are 9-point outlines of about 114 m and 101 m.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><ol><li><strong>Line style only (Q8, 10a).</strong> Every Moon route is drawn with the Mars casing, width and opacity (<code>TRAVERSE_STYLE</code>) and the same ramp, by the <strong>distance driven</strong> from the lander because the files carry no time (12a). The nation colour stays on the site marker, the INDEX dot and the panel.</li><li><strong>Furniture that needs only geometry</strong>: kilometre milestone pills (<code>distanceMilestoneStepKm</code>), the landing ring on the path, the hover card &quot;N km from landing&quot; (<code>traverse_hover_km</code>). Stops keep their rings and pills (a Moon stop has no sol, its pill is the name).</li><li><strong>Mars-only, because it needs data the Moon files do not have</strong>: sol ticks and labels, the replay marker, photo pins, the Journey tab and rover tiles. No time and no photo is invented.</li><li><strong>The two 9-point routes (11a).</strong> The LROC featured-sites list (<code>lroc.im-ldi.com/featured_sites</code>, read 2026-11-15) has a traverse page for Lunokhod 1 and 2 and Chang&#39;e 4 only; Chang&#39;e 3 has landing-site images and no traverse, and Chandrayaan-3 has no entry. The LROC GeoJSON name pattern <code>luna_change_4_traverse.geojson</code> (200 for Chang&#39;e 4) returns 404 for the Chang&#39;e 3 and Chandrayaan-3 names tried. No other source with citable coordinates was found, so both files keep their 9 points, carry <code>approximate: true</code>, and the panel (OVERVIEW tab, above the credit) says &quot;Approximate route: a simplified outline of the drive, not a surveyed track.&quot; The <code>credit</code> text says the same and names what was checked. The routes were not densified.</li></ol><h2 id="not-done-here" tabindex="-1">Not done here <a class="header-anchor" href="#not-done-here" aria-label="Permalink to &quot;Not done here&quot;">​</a></h2><ul><li>No published coordinates for Yutu or Pragyan were found; the search budget of the session ran out after the LROC listing was read. Peer-reviewed Yutu maps (CNSA / the Chang&#39;e 3 science team) and ISRO&#39;s rover-track release were not opened.</li><li>Per-point time, photo sidecars, Apollo 15 route tiles and a Journey tab for the Moon: a content project (brief §4.4), not a style change.</li></ul><h2 id="verification" tabindex="-1">Verification <a class="header-anchor" href="#verification" aria-label="Permalink to &quot;Verification&quot;">​</a></h2><p>Unit: see the commit. Browser results (screenshots, e2e) are recorded in the slice report; this record is not updated with them.</p>',10)])])}const p=t(s,[["render",n]]);export{m as __pageData,p as default};
